def algorithm(func, dim, lb, ub, budget, rng):
    n = len(lb)
    x_best = np.array([0.5 * (ub[i] + lb[i]) for i in range(n)])
    f_best = func(x_best)

    candidates = np.zeros((budget, n))
    for i in range(budget):
        for j in range(n):
            candidates[i, j] = rng.uniform(lb[j], ub[j])

        if i == 0:
            x_current = candidates[i]
        else:
            f_current = func(candidates[i])
            if f_current < f_best:
                f_best = f_current
                x_best = candidates[i]

        # Randomly perturb the current solution to create a new candidate
        delta = rng.normal(size=n, loc=0, scale=np.sqrt(1 / (i + 1)))
        x_new = x_best + 0.5 * delta

        # Clip new candidate within bounds
        for j in range(n):
            x_new[j] = max(lb[j], min(x_new[j], ub[j]))

        candidates[i+1] = x_new

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    x = lb + (ub - lb) * rng.rand(dim)
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        s = 0.1 * (func(best_x) / np.mean(func(np.clip(x, lb, ub)) ** 2)) ** 0.5
        e = rng.uniform(-s, s)
        y = x + e

        # Apply bounds to candidate
        for i in range(dim):
            if y[i] < lb:
                y[i] = lb
            elif y[i] > ub:
                y[i] = ub

        f_y = func(y)
        if f_y < best_f:
            best_x = y.copy()
            best_f = f_y

        # Random walk component with step size adaptation
        s += 0.01 * (func(best_x) / np.mean(func(np.clip(x, lb, ub)) ** 2))
        e = rng.uniform(-s, s)
        z = x + e

        for i in range(dim):
            if z[i] < lb:
                z[i] = lb
            elif z[i] > ub:
                z[i] = ub

        f_z = func(z)
        if f_z < best_f and np.random.rand() < 0.1:
            x = z.copy()

    return best_x

